begin;
-- Public copies contain only consent/booking fields. Private terms and hashes remain immutable.
create function private.customer_reward_terms(p_terms jsonb)returns jsonb language sql immutable security invoker set search_path=pg_catalog as $$
 select jsonb_build_object('rules_schema_version',p_terms->'rules_schema_version','unit',p_terms->'unit','policy_version_id',p_terms->'policy_version_id','branch_id',p_terms->'branch_id','offer_id',p_terms->'offer_id','threshold_visits',p_terms->'threshold_visits','eligible_service_ids',p_terms->'eligible_service_ids','effect_scope',p_terms->'effect_scope','redemption_enabled',p_terms->'redemption_enabled','source_channel',p_terms->'source_channel','consent_required',p_terms->'consent_required','adoption_required',p_terms->'adoption_required','original_credit_expiry_preserved',p_terms->'original_credit_expiry_preserved','offset_scope',p_terms->'offset_scope','owner_review_resolution',p_terms->'owner_review_resolution','stacking_supported',p_terms->'stacking_supported','rules',jsonb_build_object('pooling',(p_terms->'rules')->'pooling','expiry',(p_terms->'rules')->'expiry','cancellation',(p_terms->'rules')->'cancellation','refunded_contribution',(p_terms->'rules')->'refunded_contribution'),'reward_service',jsonb_build_object('id',(p_terms->'reward_service')->'id','name',(p_terms->'reward_service')->'name','is_active',(p_terms->'reward_service')->'is_active','is_public',(p_terms->'reward_service')->'is_public','branch_id',(p_terms->'reward_service')->'branch_id'),'offer',jsonb_build_object('name',(p_terms->'offer')->'name','starts_at',(p_terms->'offer')->'starts_at','ends_at',(p_terms->'offer')->'ends_at','current_is_active',(p_terms->'offer')->'current_is_active','current_is_public',(p_terms->'offer')->'current_is_public'));
$$;
revoke all on function private.customer_reward_terms(jsonb)from public,anon,authenticated,service_role;
create function private.customer_reward_quote(p_quote private.service_reward_quotes)returns jsonb language sql immutable security invoker set search_path=pg_catalog as $$
 select jsonb_build_object('quote_id',(p_quote).quote_id,'customer_id',(p_quote).customer_id,'source_channel',(p_quote).source_channel,'branch_id',(p_quote).branch_id,'service_id',(p_quote).service_id,'vehicle_id',(p_quote).vehicle_id,'booking_date',(p_quote).booking_date,'booking_time',(p_quote).booking_time,'notes',(p_quote).notes,'policy_version_id',(p_quote).policy_version_id,'rules_version_id',(p_quote).rules_version_id,'threshold_visits',(p_quote).threshold_visits,'gross_amount',(p_quote).gross_amount,'earning_ids',(p_quote).earning_ids,'adoption_ids',(p_quote).adoption_ids,'fingerprint',(p_quote).fingerprint,'expires_at',(p_quote).expires_at,'created_at',(p_quote).created_at,'terms_snapshot',private.customer_reward_terms((p_quote).terms_snapshot),'payload',jsonb_build_object('service',(p_quote).service_id,'branch',(p_quote).branch_id,'vehicle',(p_quote).vehicle_id,'date',(p_quote).booking_date,'time',(p_quote).booking_time,'policy',(p_quote).policy_version_id,'rules',(p_quote).rules_version_id,'notes',(p_quote).notes,'source_channel',(p_quote).source_channel),'allocation_snapshot',(select coalesce(jsonb_agg(jsonb_build_object('earning_id',entry->'earning_id','credit_terms',jsonb_build_object('valid',(entry->'credit_terms')->'valid','expires_at',(entry->'credit_terms')->'expires_at','adoption_required',(entry->'credit_terms')->'adoption_required','original_rules_version_id',(entry->'credit_terms')->'original_rules_version_id','effective_rules_version_id',(entry->'credit_terms')->'effective_rules_version_id'))order by ordinal),'[]'::jsonb)from jsonb_array_elements((p_quote).allocation_snapshot)with ordinality as allocated(entry,ordinal)));
$$;
revoke all on function private.customer_reward_quote(private.service_reward_quotes)from public,anon,authenticated,service_role;
create or replace function private.get_service_reward_options(p_service uuid,p_branch uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare r private.loyalty_redemption_rule_versions;programs jsonb:='[]';lots bigint;adoptions bigint;blocked jsonb;ready boolean;
begin
 if auth.uid() is null or not exists(select 1 from public.customers where id=auth.uid()) then raise exception 'Customer sign-in required' using errcode='42501';end if;
 select booking_installed and readers_integrated into ready from private.reward_runtime where singleton;
 if not coalesce(ready,false) then return jsonb_build_object('redemption_enabled',false,'programs','[]'::jsonb,'reason','checkout_not_fully_installed','unit','service_visits');end if;
 perform private.sync_customer_rewards(auth.uid());
 for r in select v.* from private.loyalty_redemption_rule_versions v join private.reward_rule_activations a using(rules_version_id) where v.branch_id=p_branch and(v.terms_snapshot#>>'{reward_service,id}')::uuid=p_service and(v.terms_snapshot->'target_customer_ids'='null'::jsonb or v.terms_snapshot->'target_customer_ids' @> to_jsonb(array[auth.uid()])) order by v.version_no desc loop
 select count(*),count(*)filter(where(credit_terms->>'adoption_required')::boolean) into lots,adoptions from private.reward_program_lots(auth.uid(),r.rules_version_id);
 blocked:=private.reward_program_blockers(auth.uid(),r.rules_version_id);
 programs:=programs||jsonb_build_array(jsonb_build_object('rules_version_id',r.rules_version_id,'policy_version_id',r.policy_version_id,'offer_id',r.offer_id,'branch_id',r.branch_id,'threshold_visits',(r.terms_snapshot->>'threshold_visits')::integer,'reward_service',private.customer_reward_terms(r.terms_snapshot)->'reward_service','rules',private.customer_reward_terms(r.terms_snapshot)->'rules','terms_snapshot',private.customer_reward_terms(r.terms_snapshot),'available_visits',lots,'pre_rule_visits',adoptions,'blockers',blocked,'eligible',lots>=(r.terms_snapshot->>'threshold_visits')::integer and(blocked->>'eligible')::boolean and(r.rules->>'expiry'='no_expiry' or(r.terms_snapshot#>>'{offer,ends_at}')::timestamptz>clock_timestamp())));
 end loop;
 return jsonb_build_object('redemption_enabled',true,'programs',programs,'unit','service_visits','legacy_imported',false,'stacking_supported',false,'walk_in_supported',false);
end $$;
create or replace function private.quote_service_reward(p_request uuid,p_service uuid,p_branch uuid,p_vehicle uuid,p_date date,p_time time,p_policy uuid,p_rules uuid,p_notes text) returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare r private.loyalty_redemption_rule_versions;s public.business_catalog_items;q private.service_reward_quotes;payload jsonb;terms jsonb;allocations jsonb;ids uuid[];adoptions uuid[];deadline timestamptz;fingerprint text;blocked jsonb;threshold integer;
begin
 if auth.uid() is null or not exists(select 1 from public.customers where id=auth.uid()) then raise exception 'Customer sign-in required' using errcode='42501';end if;
 if p_request is null or p_service is null or p_branch is null or p_vehicle is null or p_date is null or p_time is null or p_policy is null or p_rules is null or length(coalesce(p_notes,''))>2000 then raise exception 'Complete explicit reward booking details required' using errcode='22023';end if;
 payload:=jsonb_build_object('service',p_service,'branch',p_branch,'vehicle',p_vehicle,'date',p_date,'time',p_time,'policy',p_policy,'rules',p_rules,'notes',nullif(trim(p_notes),''),'source_channel','booking');
 perform pg_advisory_xact_lock(hashtextextended('reward-quote:'||p_request::text,0));select * into q from private.service_reward_quotes where quote_id=p_request;
 if q.quote_id is not null then if q.customer_id<>auth.uid() then raise exception 'Quote access denied' using errcode='42501';end if;if q.payload<>payload then raise exception 'Quote request changed' using errcode='22023';end if;return private.customer_reward_quote(q)||jsonb_build_object('eligible',q.expires_at>clock_timestamp(),'reason',case when q.expires_at<=clock_timestamp() then 'quote_expired' else 'quoted' end,'amount_due',0,'reward_discount',q.gross_amount,'adoption_required',cardinality(q.adoption_ids)>0,'unit','service_visits','currency','EGP');end if;
 if not exists(select 1 from private.reward_runtime where singleton and booking_installed and readers_integrated) then return jsonb_build_object('eligible',false,'reason','checkout_not_fully_installed');end if;
 perform private.sync_customer_rewards(auth.uid());
 select v.* into r from private.loyalty_redemption_rule_versions v join private.reward_rule_activations a using(rules_version_id) where v.rules_version_id=p_rules and v.policy_version_id=p_policy and v.branch_id=p_branch and(v.terms_snapshot#>>'{reward_service,id}')::uuid=p_service;
 if r.rules_version_id is null or(r.terms_snapshot->'target_customer_ids'<>'null'::jsonb and not(r.terms_snapshot->'target_customer_ids' @> to_jsonb(array[auth.uid()]))) then return jsonb_build_object('eligible',false,'reason','actual_activated_reward_terms_required');end if;
 blocked:=private.reward_program_blockers(auth.uid(),p_rules);if not(blocked->>'eligible')::boolean then return jsonb_build_object('eligible',false,'reason','refund_review_or_offset_required','blockers',blocked);end if;
 select * into s from public.business_catalog_items where item_id=p_service and branch_id=p_branch and item_type='service' and is_active and is_public and name !~* '(ceramic|سيراميك|paint[[:space:]]*protect|حماية[[:space:]]*الطلاء|ppf)' for share;
 if s.item_id is null or s.price<=0 or s.price::text='NaN' or not exists(select 1 from public.vehicles where id=p_vehicle and customer_id=auth.uid()) or not exists(select 1 from public.business_branches where branch_id=p_branch and is_active and not temporarily_closed) then return jsonb_build_object('eligible',false,'reason','actual_service_vehicle_or_branch_unavailable');end if;
 if(p_date+p_time) at time zone 'Africa/Cairo'<=clock_timestamp() or not exists(select 1 from private.available_booking_slots(p_branch,p_service,p_date) where slot_time=p_time) then return jsonb_build_object('eligible',false,'reason','appointment_unavailable');end if;
 threshold:=(r.terms_snapshot->>'threshold_visits')::integer;
 select array_agg(earning_id order by ord),coalesce(array_agg(earning_id order by ord)filter(where(credit_terms->>'adoption_required')::boolean),'{}'::uuid[]),jsonb_agg(jsonb_build_object('earning_id',earning_id,'credit_terms',credit_terms)order by ord),least(clock_timestamp()+interval '10 minutes',min((credit_terms->>'expires_at')::timestamptz)) into ids,adoptions,allocations,deadline from(select l.*,row_number()over(order by(credit_terms->>'expires_at')::timestamptz nulls last,earned_at,earning_id)ord from private.reward_program_lots(auth.uid(),p_rules)l order by(credit_terms->>'expires_at')::timestamptz nulls last,earned_at,earning_id limit threshold)x;
 if coalesce(cardinality(ids),0)<>threshold then return jsonb_build_object('eligible',false,'reason','insufficient_actual_eligible_visits','required_visits',threshold,'available_visits',coalesce(cardinality(ids),0));end if;
 if r.rules->>'expiry'='snapshot_offer_end' then deadline:=least(deadline,(r.terms_snapshot#>>'{offer,ends_at}')::timestamptz);end if;
 if deadline is null or deadline<=clock_timestamp() then return jsonb_build_object('eligible',false,'reason','frozen_expiry_passed');end if;
 terms:=r.terms_snapshot||jsonb_build_object('source_channel','booking','consent_required',true,'adoption_required',cardinality(adoptions)>0,'original_credit_expiry_preserved',true,'offset_scope','same_offer_and_branch','owner_review_resolution','acknowledgement_does_not_waive_debt','stacking_supported',false);
 fingerprint:=encode(extensions.digest(jsonb_build_object('payload',payload,'terms',terms,'earning_ids',ids,'allocation_snapshot',allocations,'gross_amount',s.price,'expires_at',deadline)::text,'sha256'),'hex');
 insert into private.service_reward_quotes(quote_id,customer_id,source_channel,payload,branch_id,service_id,vehicle_id,booking_date,booking_time,notes,policy_version_id,rules_version_id,threshold_visits,gross_amount,earning_ids,adoption_ids,allocation_snapshot,terms_snapshot,fingerprint,expires_at) values(p_request,auth.uid(),'booking',payload,p_branch,p_service,p_vehicle,p_date,p_time,nullif(trim(p_notes),''),p_policy,p_rules,threshold,s.price,ids,adoptions,allocations,terms,fingerprint,deadline) returning * into q;
 return private.customer_reward_quote(q)||jsonb_build_object('eligible',true,'amount_due',0,'reward_discount',q.gross_amount,'adoption_required',cardinality(q.adoption_ids)>0,'unit','service_visits','currency','EGP','collectible',false);
end $$;
create or replace function private.service_booking_attempt_view(p_request uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare a private.service_booking_attempts;r jsonb;q private.service_reward_quotes;o public.business_orders;b public.bookings;
begin
 select * into a from private.service_booking_attempts where request_id=p_request and customer_id=auth.uid();
 r:=private.service_booking_attempt_result(p_request);
 if coalesce((r->>'different_mode')::boolean,false) then return jsonb_build_object('state','different_mode','request_id',p_request);end if;
 if r is not null then
 if a.request_id is null then
 select * into o from public.business_orders where customer_id=auth.uid() and customer_request_id=p_request;select * into b from public.bookings where id=o.booking_id;
 insert into private.service_booking_attempts(request_id,customer_id,mode,payload,state,result,acknowledged_at,resolved_at) values(p_request,auth.uid(),'normal',jsonb_build_object('p_service',b.catalog_item_id,'p_branch',b.branch_id,'p_vehicle',b.vehicle_id,'p_date',b.booking_date,'p_time',b.booking_time,'p_expected_price',b.quoted_price,'p_notes',b.notes),'succeeded',r,clock_timestamp(),clock_timestamp()) returning * into a;
 elsif a.state='open' then update private.service_booking_attempts set state='succeeded',result=coalesce(result,r),resolved_at=coalesce(resolved_at,clock_timestamp()) where customer_id=auth.uid() and request_id=p_request returning * into a;
 elsif a.state='closed' then return jsonb_build_object('state','manual_review_required','request_id',p_request,'reason','closed_request_has_external_order');end if;
 return jsonb_build_object('state','succeeded','request_id',p_request,'mode',a.mode,'payload',a.payload,'result',r,'acknowledged',a.acknowledged_at is not null);end if;
 if a.request_id is null then return jsonb_build_object('state','absent','request_id',p_request);end if;
 if a.mode='reward' then select * into q from private.service_reward_quotes where quote_id=(a.payload->>'p_quote')::uuid and customer_id=auth.uid();end if;
 return jsonb_build_object('state',a.state,'request_id',p_request,'mode',a.mode,'payload',a.payload,'form_context',case when q.quote_id is null then null else private.customer_reward_quote(q) end);
end $$;
revoke all on function private.service_booking_attempt_view(uuid) from public,anon,authenticated,service_role;
notify pgrst,'reload schema';
commit;
